mapper.select:
SELECT id, value, label, status, sort_order, created_at FROM sizes
deleted_at IS NULL AND status = #{status} AND (value ILIKE CONCAT('%', #{keyword}, '%') OR label ILIKE CONCAT('%', #{keyword}, '%'))
ORDER BY sort_order ASC, value ASC LIMIT #{limit} OFFSET #{offset}

SELECT id, name AS value, name AS label, color_code, status, sort_order, created_at FROM colors
deleted_at IS NULL AND status = #{status} AND (name ILIKE CONCAT('%', #{keyword}, '%') OR color_code ILIKE CONCAT('%', #{keyword}, '%'))
ORDER BY sort_order ASC, name ASC LIMIT #{limit} OFFSET #{offset}
